    beats = {
        { id = "egg", at = 15, title = "Yellow",
            text = "I began as one of thirty yellow eggs, stood on end under a nettle leaf, right beside a crowd of aphids. My mother chose the spot and never stayed to meet us. She left us breakfast. I call that love." },
        { id = "larva", at = 40, title = "Nobody's lucky charm",
            text = "I did not hatch red. I hatched grey and spiky, all legs and appetite, more small dragon than ladybird. Nobody makes a wish on a thing like that. I ate, and grew, and told myself luck could wait." },
        { id = "pupa", at = 80, title = "Stuck",
            text = "One day I glued my tail to a leaf and could not have said why. I hung there, curled up, for a week. Wind, rain, a wasp that looked at me for too long. I could do nothing at all. I have been superstitious ever since." },
        { id = "blank", at = 140, title = "No spots",
            text = "When I climbed out I had wing covers at last. Pale yellow. Bare. I looked for one spot and found none. I thought: so I am the unlucky one. I sat on that leaf and did not dare go anywhere." },
        { id = "seven", at = 220, title = "Seven",
            text = "The spots came by evening. They rose through the yellow like ink through paper, one, then a pair, then more. I counted seven and went on counting all night. The red took days longer. I never judge a day before evening now." },
        { id = "ants", at = 320, title = "The war of the rose",
            text = "My first rose was guarded by ants. They keep aphids the way people keep cows, and they do not share. Forty of them ran at me. I folded my legs, dropped off the leaf and played dead in the grass. My sense of drama dates from then." },
        { id = "finger", at = 450, title = "The finger",
            text = "A child found me on a wall and let me climb a finger. At the tip the child said a rhyme, fly away home, and then whispered a wish, too quiet to catch. I flew. I had no notion where home was meant to be." },
        { id = "winter", at = 600, title = "Thirty in a crack",
            text = "That winter I slept under the bark of an old pear tree with thirty others, spots to spots. In my sleep I kept hearing the rhyme. Thirty of us in a row, and I was the only one still looking for an address." },
        { id = "looking", at = 800, title = "Looking",
            text = "In spring I went looking. I tried a greenhouse, a churchyard, a washing line with one red sock. Good places. Good omens, even. None was the place in the rhyme. I began to think the child had meant some other ladybird." },
        { id = "landing", at = 1050, title = "The landing",
            text = "I came over your wall on a warm wind and landed on the first pale thing I saw. A page. You did not shake me off. You waited, and read around me, until I walked to the margin. Nobody had ever read around me before." },
        { id = "wish", at = 1400, title = "The whispered wish",
            text = "I still wonder what that child wished. {total} pages have gone by in your hands and I have looked for the answer in every sign. Here is my best guess: the wish was for me. Somewhere to land. Someone who waits." },
        { id = "home", at = 1800, title = "Fly away home",
            text = "Everybody thinks the ladybird brings the luck. I landed on your book and have been the lucky one every day since, {days} of them. Fly away home, the child said. I did. Count my spots whenever you like. All seven are yours." },
    },
}
